const rows = items[0].json.rows;
const months = [...new Set(rows.map(r => r.month))];
const clients = [...new Set(rows.map(r => r.client))];
const esc = s => String(s).replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const healthClass = h => h === 'At risk' ? 'risk' : h === 'Watch' ? 'watch' : '';
const pill = h => `<span class="pill ${healthClass(h)}">${esc(h)}</span>`;
const css = `body{font:14px Arial,sans-serif;background:#F2EFE6;color:#0E0E10;margin:0;padding:32px}main{max-width:1000px;margin:auto}h1{font-size:42px}h2{margin-top:34px}.tag{font:11px 'JetBrains Mono',monospace;letter-spacing:.1em}.kpis,.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.kpi,.card{border:1px solid #D9D8CF;padding:16px}.kpi b{font-size:28px;display:block}table{border-collapse:collapse;width:100%;margin:18px 0}td,th{border-bottom:1px solid #ddd;padding:10px;text-align:left}th,.small{font:10px 'JetBrains Mono',monospace;text-transform:uppercase;color:#747B7C}.pill{background:#E8E9E0;padding:4px 7px;font:10px 'JetBrains Mono',monospace}.risk{background:#FFE1D9}.watch{background:#FFF0C6}.monthrow{display:flex;gap:8px}.month{flex:1;background:#EBEAE2;padding:10px}.bar{height:4px;background:#D4FF3A;margin-top:8px}.callout{padding:16px;background:#ECEEE1;border-left:4px solid #D4FF3A}@media(max-width:680px){.kpis,.grid{grid-template-columns:1fr}body{padding:16px}}`;
const wrap = (ticket,title,subtitle,body) => `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${title}</title><style>${css}</style></head><body><main><div class="tag">WIB ✳ WHAT I BUILT · LEADERSHIP REPORTING · DEMO DATA</div><p class="small">${ticket} · SYNTHETIC SHOWCASE</p><h1>${title}</h1><p>${subtitle}</p>${body}<p class="small">SYNTHETIC DATA · NO SOURCE SYSTEM ACCESSED</p></main></body></html>`;
const kpi=(n,label)=>`<div class="kpi"><b>${n}</b><span class="small">${label}</span></div>`;
const latest = c => rows.find(r=>r.client===c && r.month===months[months.length-1]);
const statusOf = c => latest(c).health;
const summaryRows = clients.map(c=>{const r=latest(c);return `<tr><td><b>${esc(c)}</b></td><td>${esc(r.program)}</td><td>${pill(r.health)}</td><td>${r.completion}%</td><td>${esc(r.signal)}</td></tr>`}).join('');
const clientCards = clients.map(c=>{const rs=rows.filter(r=>r.client===c);const r=rs[0];return `<article class="card"><div class="tag">CLIENT / ${esc(c)}</div><h3>${esc(r.program)} · ${pill(statusOf(c))}</h3><p>${esc(r.signal)}</p><table><tr>${rs.map(x=>`<td><b>${esc(x.month.slice(0,3))}</b><br>${x.completion}%<br>${esc(x.milestone)}</td>`).join('')}</tr></table></article>`}).join('');
const clientBody=`<div class="kpis">${kpi(clients.length,'placeholder clients')}${kpi(months.length,'reporting months')}${kpi(rows.length,'client-month updates')}</div><h2>Portfolio snapshot · ${esc(months.at(-1))}</h2><table><thead><tr><th>Client</th><th>Program</th><th>Status</th><th>Progress</th><th>Latest signal</th></tr></thead><tbody>${summaryRows}</tbody></table><h2>Client timelines · six-month view</h2><div class="grid">${clientCards}</div><h2>Sources modeled</h2><div class="callout">Gmail · Slack · Notion · Google Docs / Sheets · Jira · meeting transcripts. These normalized demo records are synthetic. Connect source credentials only after importing and reviewing this workflow.</div>`;
const wsrMonths=months.map(m=>{const rs=rows.filter(r=>r.month===m),good=rs.filter(r=>r.health==='On track').length,risk=rs.filter(r=>r.health==='At risk').length,avg=Math.round(rs.reduce((a,r)=>a+r.completion,0)/rs.length);return `<div class="month"><b>${esc(m)}</b><p>${good} on track · ${risk} at risk · ${avg}% avg progress</p><div class="bar" style="width:${avg}%"></div></div>`}).join('');
const attentionRows=clients.map(c=>{const r=latest(c);return `<tr><td><b>${esc(c)}</b><br>${esc(r.program)}</td><td>${pill(r.health)}</td><td>${esc(r.milestone)}</td><td>${esc(r.signal)}</td></tr>`}).join('');
const leadershipBody=`<div class="kpis">${kpi(clients.length,'programs tracked')}${kpi(clients.filter(c=>statusOf(c)==='On track').length,'on track · latest month')}${kpi(clients.filter(c=>statusOf(c)==='At risk').length,'at risk · latest month')}</div><h2>WSR · delivery pulse</h2><div class="monthrow">${wsrMonths}</div><table><thead><tr><th>Client</th><th>Health</th><th>Latest milestone</th><th>Leadership attention</th></tr></thead><tbody>${attentionRows}</tbody></table><h2>Product × Sales connect</h2><div class="grid"><article class="card"><div class="tag">WHAT IS MOVING</div><h3>Evidence to bring forward</h3><p>Nova: onboarding experiment shows an 8% lift in completion; confirm guardrails and rollout threshold.</p><p>Pearl: accessibility review was added after research; align release scope before sign-off.</p><p>Alpha: pilot acceptance is the near-term proof point for the core launch.</p></article><article class="card"><div class="tag">DECISIONS NEEDED</div><h3>Clear the delivery path</h3><p>Lotus: name a partner owner and date for gateway sandbox access.</p><p>Ember: assign owners to two CRM source systems before migration rehearsal.</p><p>Cedar: agree the data parity threshold before cutover.</p></article></div><h2>Next 30 days · proposed actions</h2><table><tr><th>Action</th><th>Suggested owner</th><th>Success signal</th></tr><tr><td>Confirm Lotus sandbox access</td><td>Partner lead + program</td><td>Credentials; integration test scheduled</td></tr><tr><td>Assign CRM source owners</td><td>Sales operations</td><td>Named owners; field map approved</td></tr><tr><td>Set Cedar parity threshold</td><td>Analytics + sponsor</td><td>Written threshold and exception path</td></tr><tr><td>Review Nova rollout guardrails</td><td>Product + Sales</td><td>Decision logged with adoption measures</td></tr></table><div class="callout"><b>Meeting framing:</b> Four programs are on track. The two risks have clear next steps: gateway sandbox access at Lotus and CRM data ownership at Ember. Today, confirm owners and dates.</div>`;
return [{json:{report:'client_status',filename:'client-status-report.html',html:wrap('WIB-001','Client-wise status report','A six-month, six-client portfolio view assembled from normalized delivery signals.',clientBody)}},{json:{report:'leadership_connect',filename:'leadership-connect-report.html',html:wrap('WIB-002','Leadership connect report','WSR and Product × Sales meeting brief with health, movement, decisions and proposed actions.',leadershipBody)}}];
